const sourceItems = $input.all().flatMap(item => {
  if (Array.isArray(item.json)) {
    return item.json.map(source => ({ json: source }));
  }

  return [item];
});

return sourceItems
  .filter(item => item.json.active === true && String(item.json.type || '').toUpperCase() === 'RSS')
  .sort((left, right) => (left.json.priority || 0) - (right.json.priority || 0));

const normalized = [];
const sourceItems = $('Filter Active RSS Sources').all();

function asArray(value) {
  if (value === undefined || value === null) {
    return [];
  }

  return Array.isArray(value) ? value : [value];
}

function firstWith(candidates, propertyName) {
  return candidates
    .flatMap(asArray)
    .find(candidate => candidate && candidate[propertyName]);
}

function pickValue(value) {
  if (value === undefined || value === null) {
    return '';
  }

  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }

  if (Array.isArray(value)) {
    return pickValue(value.find(entry => pickValue(entry).trim() !== '') || value[0]);
  }

  return pickValue(value._value || value._ || value['#text'] || value.href || value.url || value.guid);
}

function cleanText(value) {
  return pickValue(value)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizePublishedAt(value) {
  const rawValue = pickValue(value).trim();

  if (!rawValue) {
    return null;
  }

  const timestamp = Date.parse(rawValue);

  if (Number.isNaN(timestamp)) {
    return null;
  }

  return new Date(timestamp).toISOString();
}
function resolveUrl(value, sourceUrl) {
  const rawUrl = pickValue(value).trim();

  if (!rawUrl) {
    return '';
  }

  if (/^https?:\/\//i.test(rawUrl)) {
    return rawUrl;
  }

  if (rawUrl.startsWith('//')) {
    const protocolMatch = String(sourceUrl).match(/^(https?:)/i);
    return (protocolMatch ? protocolMatch[1] : 'https:') + rawUrl;
  }

  const originMatch = String(sourceUrl).match(/^(https?:\/\/[^/]+)/i);
  if (!originMatch) {
    return rawUrl;
  }

  const origin = originMatch[1];

  if (rawUrl.startsWith('/')) {
    return origin + rawUrl;
  }

  const basePath = String(sourceUrl)
    .replace(/[#?].*$/, '')
    .replace(/\/[^/]*$/, '/');

  return basePath + rawUrl;
}

function findAtomUrl(entry, sourceUrl) {
  const contentLink = entry.content?.div?.a?.href || entry.content?.a?.href;
  if (contentLink) {
    return resolveUrl(contentLink, sourceUrl);
  }

  for (const link of asArray(entry.link)) {
    const candidate = resolveUrl(link?.href || link, sourceUrl);
    if (candidate) {
      return candidate;
    }
  }

  return resolveUrl(entry.id, sourceUrl);
}

function atomSummary(entry) {
  const paragraphs = asArray(entry.content?.div?.p);

  if (paragraphs.length > 0) {
    return paragraphs
      .map(paragraph => cleanText(`${pickValue(paragraph.strong)} ${pickValue(paragraph._ || paragraph['#text'])}`))
      .filter(Boolean)
      .join(' | ');
  }

  return cleanText(entry.summary || entry.content || '');
}

function sourceForInput(item, index) {
  const pairedIndex = item.pairedItem?.item;

  if (pairedIndex !== undefined && sourceItems[pairedIndex]?.json) {
    return sourceItems[pairedIndex].json;
  }

  return sourceItems[index]?.json || {};
}

for (let index = 0; index < $input.all().length; index++) {
  const item = $input.all()[index];
  const source = sourceForInput(item, index);
  const sourceId = item.json.sourceId || source.id;
  const sourceUrl = source.url || '';

  if (!sourceId) {
    continue;
  }

  const jsonData = item.json.data && typeof item.json.data === 'object' ? item.json.data : item.json;

  const atomRoot = firstWith([
    jsonData.feed,
    jsonData.root?.feed,
    jsonData.body?.feed,
    jsonData.data?.feed,
    jsonData.root,
    jsonData.body,
    jsonData
  ], 'entry');

  if (atomRoot?.entry) {
    for (const entry of asArray(atomRoot.entry)) {
      const title = cleanText(entry.title) || 'Sin titulo';
      const url = findAtomUrl(entry, sourceUrl);
      const summary = atomSummary(entry);
      const content = cleanText(entry.content || entry.summary || summary);

      if (!url) {
        continue;
      }

      normalized.push({
        json: {
          sourceId,
          title,
          url,
          summary,
          content,
          publishedAt: normalizePublishedAt(entry.published || entry.updated)
        }
      });
    }

    continue;
  }

  const channel = firstWith([
    jsonData.rss?.channel,
    jsonData.channel,
    jsonData.root?.rss?.channel,
    jsonData.root?.channel,
    jsonData.body?.rss?.channel,
    jsonData.body?.channel,
    jsonData.data?.rss?.channel,
    jsonData.data?.channel,
    jsonData
  ], 'item');

  if (channel?.item) {
    for (const article of asArray(channel.item)) {
      const title = cleanText(article.title) || 'Sin titulo';
      const url = resolveUrl(article.link || article.guid, sourceUrl);
      const summary = cleanText(article.description || article.summary);
      const content = cleanText(article['content:encoded'] || article.content || article.description || summary);

      if (!url) {
        continue;
      }

      normalized.push({
        json: {
          sourceId,
          title,
          url,
          summary,
          content,
          publishedAt: normalizePublishedAt(article.pubDate || article.published || article.updated || article['dc:date'])
        }
      });
    }
  }
}

return normalized;

const seen = new Set();
const batch = [];

for (const item of $input.all()) {
  const url = item.json.url;

  if (!url || seen.has(url)) {
    continue;
  }

  seen.add(url);
  batch.push(item.json);
}

if (batch.length === 0) {
  return [];
}

return [{ json: { batch } }];
